SELECT f.id,f.title,f.artist,f.version_label,f.description,f.submitted_by,f.source,f.status,f.handling_note,f.resolved_song_id,f.resolved_song_title,f.resolved_song_artists_json,f.revision,f.created_at,f.updated_at,f.resolved_at,f.creation_hash,EXISTS(SELECT 1 FROM media_song s JOIN media_source src ON src.id=s.source_id WHERE s.id=f.resolved_song_id) AS resolved_song_available FROM missing_song_feedback f WHERE (?='' OR search_text LIKE ? ESCAPE '!') AND (?='ALL' OR status=?) ORDER BY created_at DESC,id ASC LIMIT ? OFFSET ?
